const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const uk = countries.filter(ee.Filter.eq('ADM0_NAME', 'United Kingdom'));
  const geometry = uk.geometry();

  // Target period: February 11-25, 2019
  const date_2019_start = '2019-02-11';
  const date_2019_end = '2019-02-25';

  // Baseline period: February 11-25, 2000-2012
  const baseline_years_start = 2000;
  const baseline_years_end = 2012;

  const LST_COLLECTION = 'MODIS/061/MOD11A2'; // 8-day composite LST
  const LST_BAND = 'LST_Day_1km';
  const QC_BAND = 'QC_Day';
  const SCALE = 0.02; // LST scale factor
  const KELVIN_TO_CELSIUS_OFFSET = 273.15;

  // Function to mask clouds and scale LST
  const maskAndScaleLST = function(image) {
    const qc = image.select(QC_BAND);
    // Bits 0-1: Mandatory QA flags
    // 00: LST produced, good quality, not used LST_Err_Amb
    const goodQuality = qc.bitwiseAnd(3).eq(0);

    let lst = image.select(LST_BAND)
                   .updateMask(goodQuality); // Apply good quality mask

    // Mask out 0 values (often no data)
    lst = lst.updateMask(lst.gt(0));

    // Scale and convert to Celsius
    lst = lst.multiply(SCALE).subtract(KELVIN_TO_CELSIUS_OFFSET);

    return image.addBands(lst.rename('LST_Celsius'));
  };

  // 2. Data Acquisition & Check for 2019
  let collection_2019 = ee.ImageCollection(LST_COLLECTION)
                          .filterDate(date_2019_start, date_2019_end)
                          .filterBounds(geometry)
                          .map(maskAndScaleLST)
                          .select('LST_Celsius');

  let size_2019 = await collection_2019.size().getInfo();
  if (size_2019 === 0) {
    console.log("2019 Images: 0. Could not find any images for the target period.");
    console.log("C1");
    return;
  }
  console.log(`2019 Images found: ${size_2019}`);

  // Calculate mean LST for 2019
  let mean_2019 = collection_2019.mean();
  let pixels_2019 = mean_2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 5000, // MODIS 1km, so 5km is safe
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  if (pixels_2019 === null || pixels_2019 === 0) {
    console.log(`2019 Pixels: ${pixels_2019}. No valid pixels after masking for 2019.`);
    console.log("C2");
    return;
  }

  let lst_2019_val = await mean_2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 5000,
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  if (lst_2019_val === null || isNaN(lst_2019_val)) {
    console.log(`2019 LST calculation failed: ${lst_2019_val}`);
    console.log("C3");
    return;
  }
  console.log(`2019 LST: ${lst_2019_val.toFixed(2)} °C (Pixels: ${pixels_2019})`);


  // Data Acquisition & Check for Baseline period (2000-2012)
  let baseline_collection = ee.ImageCollection([]);

  for (let year = baseline_years_start; year <= baseline_years_end; year++) {
    const year_start_date = `${year}-02-11`;
    const year_end_date = `${year}-02-25`;

    let year_collection = ee.ImageCollection(LST_COLLECTION)
                            .filterDate(year_start_date, year_end_date)
                            .filterBounds(geometry)
                            .map(maskAndScaleLST)
                            .select('LST_Celsius');

    baseline_collection = baseline_collection.merge(year_collection);
  }

  let size_baseline = await baseline_collection.size().getInfo();
  if (size_baseline === 0) {
    console.log("Baseline Images: 0. Could not find any images for the 2000-2012 baseline period.");
    console.log("C1");
    return;
  }
  console.log(`Baseline Images found (2000-2012): ${size_baseline}`);

  let mean_baseline = baseline_collection.mean();
  let pixels_baseline = mean_baseline.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 5000,
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  if (pixels_baseline === null || pixels_baseline === 0) {
    console.log(`Baseline Pixels: ${pixels_baseline}. No valid pixels after masking for baseline period.`);
    console.log("C2");
    return;
  }

  let lst_baseline_val = await mean_baseline.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 5000,
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  if (lst_baseline_val === null || isNaN(lst_baseline_val)) {
    console.log(`Baseline LST calculation failed: ${lst_baseline_val}`);
    console.log("C3");
    return;
  }
  console.log(`Baseline LST (2000-2012 avg): ${lst_baseline_val.toFixed(2)} °C (Pixels: ${pixels_baseline})`);

  // 5. Validation & Final Answer
  if (lst_2019_val > lst_baseline_val) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
